#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    vector<int> a(n);
    for (auto &x : a) scanf("%d", &x);
    int k;
    scanf("%d", &k);
    // dp[v] = longest valid subsequence so far ending with value v (values < 2^20, so xor < 2^21).
    vector<int> dp(1 << 21, 0);
    int best = 1;
    for (int v : a) {
        dp[v] = max(dp[v], dp[v ^ k] + 1);
        best = max(best, dp[v]);
    }
    printf("%d\n", best);
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken(); int n = (int) st.nval;
        int[] a = new int[n];
        for (int i = 0; i < n; i++) { st.nextToken(); a[i] = (int) st.nval; }
        st.nextToken(); int k = (int) st.nval;
        // dp[v] = longest valid subsequence so far ending with value v (values < 2^20, so xor < 2^21).
        int[] dp = new int[1 << 21];
        int best = 1;
        for (int v : a) {
            dp[v] = Math.max(dp[v], dp[v ^ k] + 1);
            best = Math.max(best, dp[v]);
        }
        System.out.println(best);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<16)
	var n int
	fmt.Fscan(in, &n)
	a := make([]int, n)
	for i := range a {
		fmt.Fscan(in, &a[i])
	}
	var k int
	fmt.Fscan(in, &k)
	// dp[v] = longest valid subsequence so far ending with value v (values < 2^20, so xor < 2^21).
	dp := make([]int, 1<<21)
	best := 1
	for _, v := range a {
		dp[v] = max(dp[v], dp[v^k]+1)
		best = max(best, dp[v])
	}
	fmt.Println(best)
}
